def TK(talk, q, o, e=""):
    """Part 3/4 听力题：只放录音（对话或独白），题干和选项可见 —— 和考场一样先读题再听"""
    return CS("🎧 " + q, o, "原文：" + talk + ("　" + e if e else ""), say=talk)
